"""Self-contained staging safety tests; generated bytes are not commercial ROMs."""
import importlib.util
import io
import os
from pathlib import Path
import tempfile
import unittest
from unittest import mock
import zipfile

MODULE = Path(__file__).resolve().parents[1] / 'src/plugin.games.foundry/resources/lib/staging.py'
spec = importlib.util.spec_from_file_location('foundry_staging', str(MODULE))
staging = importlib.util.module_from_spec(spec)
spec.loader.exec_module(staging)


class MemoryIO:
    def __init__(self, data):
        self.data = data

    def open(self, path, mode='rb'):
        return io.BytesIO(self.data[path])

    def exists(self, path):
        return path in self.data


class StagingTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name).resolve()
        self.source = self.root / 'source'
        self.source.mkdir()
        self.cache = self.root / 'cache'

    def tearDown(self):
        self.temp.cleanup()

    def put(self, path, contents=b'game'):
        result = self.source / path
        result.parent.mkdir(parents=True, exist_ok=True)
        result.write_bytes(contents)
        return str(result)

    def prepare(self, source, system='nes', **kwargs):
        return staging.prepare(source, system, str(self.cache), **kwargs)

    def archive(self, members, name='game.zip'):
        path = self.source / name
        with zipfile.ZipFile(str(path), 'w', zipfile.ZIP_DEFLATED) as z:
            for filename, data in members:
                z.writestr(filename, data)
        return str(path)

    def assert_clean(self):
        self.assertFalse(list(self.cache.glob('.preparing-*')))

    def test_copy_local_and_preserve_original(self):
        source = self.put('homebrew.nes')
        result = self.prepare(source)
        self.assertEqual(Path(result).read_bytes(), b'game')
        self.assertEqual(Path(source).read_bytes(), b'game')
        self.assertNotEqual(result, source)
        self.assert_clean()

    def test_reuse_immutable_content_addressed_cache(self):
        source = self.put('homebrew.nes')
        first = self.prepare(source)
        self.assertEqual(first, self.prepare(source))
        Path(source).write_bytes(b'new version')
        second = self.prepare(source)
        self.assertNotEqual(first, second)
        self.assertEqual(Path(first).read_bytes(), b'game')

    def test_corrupt_cached_game_never_reused(self):
        source = self.put('homebrew.nes')
        first = self.prepare(source)
        Path(first).write_bytes(b'corrupt')
        with self.assertRaisesRegex(staging.StagingError, 'Cached game'):
            self.prepare(source)
        self.assertEqual(Path(source).read_bytes(), b'game')
        self.assert_clean()

    def test_local_symlink_check_without_host_privileges(self):
        source = self.put('homebrew.nes')
        original = staging.os.path.islink
        def islink(path):
            return str(path).endswith('homebrew.nes') or original(path)
        with mock.patch.object(staging.os.path, 'islink', side_effect=islink):
            with self.assertRaisesRegex(staging.StagingError, 'Symbolic'):
                self.prepare(source)

    def test_vfs_binary_adapter(self):
        adapter = MemoryIO({'smb://server/roms/a.nes': b'test'})
        result = self.prepare('smb://server/roms/a.nes', io=adapter)
        self.assertEqual(Path(result).read_bytes(), b'test')

    def test_vfs_nested_playlist_companions(self):
        adapter = MemoryIO({
            'smb://host/games/game.m3u': b'#EXTM3U\ndisc 1/a.cue\n',
            'smb://host/games/disc 1/a.cue': b'FILE "track.bin" BINARY\n TRACK 01 MODE2/2352\n',
            'smb://host/games/disc 1/track.bin': b'track',
        })
        result = Path(self.prepare('smb://host/games/game.m3u', 'psx', io=adapter))
        self.assertEqual((result.parent / 'disc 1/track.bin').read_bytes(), b'track')

    def test_missing_companion_is_atomic(self):
        source = self.put('game.cue', b'FILE "missing.bin" BINARY\n')
        with self.assertRaises(staging.StagingError):
            self.prepare(source, 'psx')
        self.assertEqual([p for p in self.cache.iterdir() if p.name != '.prepare.lock'], [])
        self.assertTrue(Path(source).exists())

    def test_cue_traversal_and_absolute_and_url_rejected(self):
        for reference in ('../secret.bin', '/secret.bin', 'C:\\secret.bin',
                          'smb://elsewhere/secret.bin', '..\\secret.bin'):
            with self.subTest(reference=reference):
                source = self.put('game.cue', ('FILE "' + reference + '" BINARY\n').encode())
                with self.assertRaises(staging.StagingError):
                    self.prepare(source, 'psx')
                self.assert_clean()

    def test_cycle_rejected(self):
        source = self.put('a.m3u', b'b.m3u\n')
        self.put('b.m3u', b'a.m3u\n')
        with self.assertRaisesRegex(staging.StagingError, 'Cyclic'):
            self.prepare(source, 'psx')

    def test_empty_and_malformed_descriptor(self):
        for data in (b'FILE broken\n', b'REM empty\n', b'FILE "a.bin" BINARY\n\xff'):
            with self.subTest(data=data):
                with self.assertRaises(staging.StagingError):
                    self.prepare(self.put('game.cue', data), 'psx')

    def test_descriptor_size_bound(self):
        with self.assertRaisesRegex(staging.StagingError, 'descriptor'):
            self.prepare(self.put('game.m3u', b'x' * (staging.DISC_LIMIT + 1)), 'psx')

    def test_nested_zip_rom(self):
        source = self.archive([('folder/readme.txt', 'license'), ('folder/demo.nes', b'nes')])
        result = Path(self.prepare(source))
        self.assertEqual(result.read_bytes(), b'nes')
        self.assertEqual(result.name, 'demo.nes')

    def test_arcade_zip_remains_intact(self):
        source = self.archive([('chip1.bin', b'one'), ('chip2.bin', b'two')])
        result = self.prepare(source, 'arcade')
        self.assertEqual(Path(source).read_bytes(), Path(result).read_bytes())
        self.assertTrue(result.endswith('.zip'))

    def test_unsupported_suffixes_are_not_guessed(self):
        for system, suffix in [('nes', '.bin'), ('arcade', '.7z'), ('arcade', '.bin')]:
            with self.subTest(system=system, suffix=suffix):
                with self.assertRaises(staging.StagingError):
                    self.prepare(self.put('game' + suffix), system)

    def test_local_source_checked_even_with_vfs_adapter(self):
        source = self.put('game.nes')
        adapter = MemoryIO({source.replace('\\', '/'): b'test'})
        with mock.patch.object(staging, '_local_safe', wraps=staging._local_safe) as check:
            self.prepare(source, io=adapter)
            self.assertEqual(check.call_count, 2)

    def test_cache_writer_lock_is_exclusive(self):
        source = self.put('game.nes')
        calls = [0]
        def callback():
            calls[0] += 1
            if calls[0] == 2:
                with self.assertRaisesRegex(staging.StagingError, 'Another game'):
                    self.prepare(source)
            return False
        self.prepare(source, cancelled=callback)
        self.assertGreater(calls[0], 2)
        self.prepare(source)  # Lock released after success.

    def test_zip_playlist_retains_discs(self):
        source = self.archive([
            ('collection.m3u', 'disc1/game.cue\ndisc2/game.cue\n'),
            ('disc1/game.cue', 'FILE "track.bin" BINARY\n'),
            ('disc1/track.bin', b'first'),
            ('disc2/game.cue', 'FILE "track.bin" BINARY\n'),
            ('disc2/track.bin', b'second')])
        result = Path(self.prepare(source, 'psx'))
        self.assertEqual(result.name, 'collection.m3u')
        self.assertEqual((result.parent / 'disc2/track.bin').read_bytes(), b'second')

    def test_zip_missing_disc_companion(self):
        source = self.archive([('game.cue', 'FILE "absent.bin" BINARY')])
        with self.assertRaisesRegex(staging.StagingError, 'Missing'):
            self.prepare(source, 'psx')

    def test_zip_traversal_cases(self):
        for name in ('../escape.nes', '..\\escape.nes', '/escape.nes',
                     'C:/escape.nes', 'smb://host/escape.nes', 'a/../escape.nes',
                     'nul.nes', 'a./game.nes', 'a//game.nes'):
            with self.subTest(name=name):
                source = self.archive([(name, b'bad'), ('good.nes', b'good')])
                with self.assertRaises(staging.StagingError):
                    self.prepare(source)
                self.assert_clean()
        self.assertFalse((self.root / 'escape.nes').exists())

    def test_zip_duplicates_and_directory_aliases(self):
        cases = [ [('a.nes', b'a'), ('A.nes', b'b')],
                  [('x/a.nes', b'a'), ('X/b.txt', b'b')],
                  [('x', b'a'), ('x/game.nes', b'b')] ]
        for members in cases:
            with self.subTest(members=members):
                with self.assertRaises(staging.StagingError):
                    self.prepare(self.archive(members))

    def test_zip_symlink(self):
        path = self.source / 'link.zip'
        with zipfile.ZipFile(str(path), 'w') as z:
            info = zipfile.ZipInfo('link.nes')
            info.create_system = 3
            info.external_attr = (0o120777 << 16)
            z.writestr(info, '../escape')
        with self.assertRaisesRegex(staging.StagingError, 'symbolic'):
            self.prepare(str(path))

    def test_local_symlink_rejected_when_supported(self):
        target = self.put('target.nes')
        link = self.source / 'link.nes'
        try:
            link.symlink_to(target)
        except OSError:
            self.skipTest('Host does not permit symlink creation')
        with self.assertRaisesRegex(staging.StagingError, 'Symbolic'):
            self.prepare(str(link))

    def test_unknown_system_and_psp_blocked(self):
        source = self.put('demo.bin')
        for system in ('unknown', 'psp'):
            with self.subTest(system=system):
                with self.assertRaises(staging.StagingError):
                    self.prepare(source, system)

    def test_ambiguous_zip_blocked(self):
        for members in ([('a.nes', b'a'), ('b.nes', b'b')], [('unknown.bin', b'a')]):
            with self.subTest(members=members):
                with self.assertRaisesRegex(staging.StagingError, 'unambiguous'):
                    self.prepare(self.archive(members))

    def test_archive_count_bound(self):
        source = self.archive([('game.nes', b'a'), ('extra.txt', b'b')])
        with self.assertRaisesRegex(staging.StagingError, 'entry limit'):
            self.prepare(source, max_entries=1)

    def test_archive_bomb_bound(self):
        source = self.archive([('game.nes', b'0' * 10000)])
        with self.assertRaisesRegex(staging.StagingError, 'size limit'):
            self.prepare(source, max_bytes=1000)
        self.assert_clean()

    def test_rom_byte_bound(self):
        source = self.put('game.nes', b'x' * 20)
        with self.assertRaisesRegex(staging.StagingError, 'size limit'):
            self.prepare(source, max_bytes=10)
        self.assert_clean()

    def test_cache_full_preserves_existing_games(self):
        first = self.prepare(self.put('first.nes', b'a' * 20))
        with self.assertRaisesRegex(staging.StagingError, 'cache size'):
            self.prepare(self.put('second.nes', b'b' * 20), max_cache_bytes=30)
        self.assertEqual(Path(first).read_bytes(), b'a' * 20)
        self.assert_clean()

    def test_cancel_before_staging(self):
        with self.assertRaises(staging.Cancelled):
            self.prepare(self.put('game.nes'), cancelled=lambda: True)
        self.assertFalse(self.cache.exists())

    def test_cancel_during_copy_removes_partial_only(self):
        calls = [0]
        def cancel():
            calls[0] += 1
            return calls[0] > 2
        source = self.put('game.nes', b'x' * (staging.CHUNK + 1))
        with self.assertRaises(staging.Cancelled):
            self.prepare(source, cancelled=cancel)
        self.assertEqual([p for p in self.cache.iterdir() if p.name != '.prepare.lock'], [])
        self.assertTrue(Path(source).exists())

    def test_corrupt_zip_is_clean(self):
        with self.assertRaises(staging.StagingError):
            self.prepare(self.put('bad.zip', b'not a zip'))
        self.assert_clean()

    def test_vfs_failure_leaves_no_cache_entry(self):
        class Broken(MemoryIO):
            def open(self, path, mode='rb'):
                raise OSError('provider unavailable')
        with self.assertRaises(staging.StagingError):
            self.prepare('smb://host/rom.nes', io=Broken({'smb://host/rom.nes': b''}))
        self.assertEqual([p for p in self.cache.iterdir() if p.name != '.prepare.lock'], [])


if __name__ == '__main__':
    unittest.main()
